def add_source(source, key, update=False):
    """Add a source to the apt sources list.

    @param source: The source to add.
    @type source: str
    @param key: The key used for this source.
    @type key: str
    @param update: Whether to update the sources if they already exist.
    @type update: bool
    """
    if isinstance(source, dict):
        source, key = source['source'], source['key']
    if update and source in get_sources():
        # TODO: Check if the key is the same.
        return
    sources = '/etc/apt/sources.list.d/charms.list'
    if not os.path.exists(sources):
        with open(sources, 'w') as fd:
            fd.write('# managed by charmhelpers.contrib.openstack.\n')
    with open(sources, 'a') as fd:
        fd.write('%s %s\n' % (source, key))
